extractedSupportingSource.validators:
const validCharacter = ((v) => typeof v === "string" && CHARACTER_IDS.includes(v));
const validInput = ((v) => {
    if (!v || typeof v !== "object")
        return false;
    const a = v;
    return (Number.isFinite(a.move) &&
        Math.abs(a.move) <= 1 &&
        ["jump", "attack", "special", "guard"].every((k) => typeof a[k] === "boolean"));
});function isSnapshot(value) {
    if (!value || typeof value !== "object")
        return false;
    const m = value;
    return (Number.isSafeInteger(m.tick) &&
        m.tick >= 0 &&
        ["countdown", "race", "transition", "fight", "results"].includes(m.phase) &&
        Number.isFinite(m.phaseTime) &&
        Array.isArray(m.players) &&
        m.players.length === 2 &&
        m.players.every((p) => validCharacter(p.character) &&
            [p.x, p.y, p.z, p.hp, p.speed, p.draft, p.dodgeCooldown, p.counterWindow, p.strikeWindup].every(Number.isFinite) &&
            p.strikeWindup > 0 && typeof p.drafting === "boolean" && typeof p.action === "string") &&
        Array.isArray(m.events) &&
        m.events.length < 128);
}
